	\mathbf E\big[((a + Z)^2 - n)_+\big]
		&= \mathbf E\big[(a^2+2aZ +Z^2-n)_+\big] \\
		&\le \mathbf E\big[(a^2+2aZ-n)_+\big]  + \mathbf E[Z^2]\\
		&\le |a^2-n| + 2a\mathbf E[Z_+]  + \mathbf E[Z^2].
\end{align}
Taking $a = \mathbf E[s_{\max}(\boldsymbol\zeta_{1:n})]$ and $Z = s_{\max}(\boldsymbol\zeta_{1:n})
-\mathbf E[s_{\max}(\boldsymbol\zeta_{1:n})]$, we get
\begin{align}
\mathbf E\big[(s_{\max}(\boldsymbol\zeta_{1:n})^2-n)_+\big]
		&\le |(\sqrt{n} + \sqrt{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}})^2-n| + (\sqrt{n} + \sqrt{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}})
		\sqrt{2\pi}  + 4\\
		&= 2\sqrt{n\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}} +\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma} + (\sqrt{n} + \sqrt{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}})
		\sqrt{2\pi}  + 4\\
		&\le 6\sqrt{n\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}} + 4\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma},\qquad \forall n\ge 8.
\end{align}
Similarly, we have
\begin{align}
	\mathbf E\big[( n - (a + Z)^2 )_+\big]
		&= \mathbf E\big[(n- a^2 - 2aZ  - Z^2)_+\big] 
		\le (n- a^2)_+ +2a\mathbf E\big[ Z_-\big].
\end{align}
Taking $a = \mathbf E[s_{\min}(\boldsymbol\xi_{1:n})]$ and $Z = s_{\min}(\boldsymbol\xi_{1:n})
-\mathbf E[s_{\min}(\boldsymbol\xi_{1:n})]$, we get
\begin{align}
	\mathbf E\big[(n-s_{\min}(\boldsymbol\xi_{1:n})^2)_+\big] &\le 
	(n- \mathbf E[s_{\min}(\boldsymbol\xi_{1:n})]^2)_+ +\mathbf E[s_{\min}(\boldsymbol\xi_{1:n})]
	\sqrt{2\pi}\\
	&\le (n- (\sqrt{n} - \sqrt{p})^2)_++
	(\sqrt{n} + \sqrt{p})\sqrt{2\pi}\\
	&\le 2\sqrt{np} +(\sqrt{n} + \sqrt{p})\sqrt{2\pi}\le 
	6\sqrt{np}.
\end{align}
Thus, we have checked \eqref{esp:1b} and \eqref{esp:1c}. 

