    The first step of the proof consists in establishing 
    a recurrent inequality relating the estimation error 
    of $\widehat{\boldsymbol\mu}^{k}$ to that of $\widehat{\boldsymbol\mu}^{k-1}$. More 
    precisely, we show that this error decreases at a 
    geometric rate, up to a small additive error term. 
    Without loss of generality, we assume that 
    $\|\boldsymbol\Sigma\|_{\textup{op}} = 1$.

    Let us recall the notation
    \begin{align}
        \mathcal W_n(\varepsilon) = \Big\{\boldsymbol w\in \boldsymbol\Delta^{n-1}: 
        \max_i w_i\le \frac1{n(1-\varepsilon)}\Big\}
    \end{align}
    and
    \begin{align}
        R(\boldsymbol\zeta,\boldsymbol w,I) = 2\varepsilon_w + \sqrt{2\varepsilon_w}
        \lambda^{1/2}_{\max,+}\bigg(\sum_{i\in I} (
        \boldsymbol w_{|I})_i(\boldsymbol\Sigma - \boldsymbol\zeta_i\boldsymbol\zeta_i^\top)\bigg)
        +(1+\sqrt{2\varepsilon_w})\|\bar{\boldsymbol\zeta}_{\boldsymbol w|I}\|_2.
    \end{align}
    For every $k\ge 1$, in view of \Cref{proposition1} and 
    \eqref{eq:minG}, we have 
    \begin{align}
        \|\widehat{\boldsymbol\mu}^{k}-\boldsymbol\mu^*\|_2 
        &\le \frac{\sqrt{\varepsilon_k}}{
        1-\varepsilon_k} G(\widehat{\boldsymbol w}^k,\widehat{\boldsymbol\mu}^{k})^{1/2} + \Xi\\
        &\le \frac{\sqrt{\varepsilon_k}}{
        1-\varepsilon_k} G(\widehat{\boldsymbol w}^k,\widehat{\boldsymbol\mu}^{k-1})^{1/2} + \Xi,\label{mu:k}
    \end{align}
    where 
    \begin{align}\label{epsk}
        \varepsilon_k = \sum_{i\not\in\mathcal I} w_i^{k}\le 
    \frac{\varepsilon n }{n-n\varepsilon} = \frac{\varepsilon}{1-
    \varepsilon}
    \end{align}
    and
    \begin{align}
        \Xi = \max_{|I|\ge n-n\varepsilon} \sup_{\boldsymbol w\in \mathcal W_n
        (\varepsilon)} R(\boldsymbol\zeta,\boldsymbol w,I).
    \end{align}
    Inequality \eqref{epsk} and the cat that the function $x\mapsto 
    \sqrt{x}/(1-x)$ is increasing for $x\in[0,1)$ imply that
    \begin{align}
        \frac{\sqrt{\varepsilon_k}}{
        1-\varepsilon_k} \le \frac{\sqrt{\varepsilon(1-\varepsilon)}}{
        1-2\varepsilon} = \alpha_\varepsilon.
    \end{align}
    Using this inequality and the fact that $\widehat{\boldsymbol w}^k$ is a minimizer
    of $G(\cdot, \widehat{\boldsymbol\mu}^{k-1})$, we infer from 
    \eqref{mu:k} that
    \begin{align}\label{mu:k1}
        \|\widehat{\boldsymbol\mu}^{k}-\boldsymbol\mu^*\|_2 &\le \alpha_\varepsilon
        G(\widehat{\boldsymbol w}^k,\widehat{\boldsymbol\mu}^{k-1})^{1/2} + \Xi\\
        &\le \alpha_\varepsilon
        G(\boldsymbol w^*_{\mathcal I},\widehat{\boldsymbol\mu}^{k-1})^{1/2} + \Xi,
    \end{align}
     where $\boldsymbol w^*_{\mathcal I}$ is the weight vector defined by 
    $w^*_i = \mathds 1(i\in\mathcal I)/|\mathcal I|$.
    One can check that
	\begin{align}
		\sum_{i=1}^n  w_i^* (\boldsymbol X_i-\widehat{\boldsymbol\mu}^{k-1})^{\otimes 2} &= 
		\sum_{i=1}^n w_i^*(\boldsymbol X_i-\bar{\boldsymbol X}_{\boldsymbol w^*_{\mathcal I}})^{\otimes 2} 
		+ (\bar{\boldsymbol X}_{\boldsymbol w^*_{\mathcal I}}-\widehat{\boldsymbol\mu}^{k-1})^{\otimes 2}\\
		&\preceq \sum_{i=1}^n w_i^*(\boldsymbol X_i-\bar{\boldsymbol X}_{\boldsymbol w^*_{\mathcal I}})^{\otimes 2}
		+ \big\|\bar{\boldsymbol X}_{\boldsymbol w^*_{\mathcal I}}-\widehat{\boldsymbol\mu}^{k-1}\big\|_2^2\,\mathbf I_p\\
		&\preceq \sum_{i=1}^n w_i^*(\boldsymbol X_i-\boldsymbol\mu^*)^{\otimes 2}
		 + \big\|\bar{\boldsymbol X}_{\boldsymbol w^*_{\mathcal I}}-\widehat{\boldsymbol\mu}^{k-1}\big\|_2^2\,\mathbf I_p.
	\end{align}	
	This readily yields
	\begin{align}
		G(\boldsymbol w^*_{\mathcal I},\widehat{\boldsymbol\mu}^{k-1}) &\le \lambda_{\max,+}
		    \bigg(\sum_{i=1}^n 
			w_i^*(\boldsymbol X_i-\boldsymbol\mu^*)^{\otimes 2} - \boldsymbol\Sigma\bigg) + 
			\big\|\bar{\boldsymbol X}_{\boldsymbol w^*_{\mathcal I}}-\widehat{\boldsymbol\mu}^{k-1}\big\|_2^2\\
			&\le G(\boldsymbol w^*_{\mathcal I}, \boldsymbol\mu^*)  + 
			\big(\big\|\bar{\boldsymbol\zeta}_{\boldsymbol w^*_{\mathcal I}}\big\|_2 + 
			\big\|\boldsymbol\mu^*-\widehat{\boldsymbol\mu}^{k-1}\big\|_2\big)^2.
	\end{align}
	Combining with inequality \eqref{mu:k1}, we arrive at
	\begin{align}
        \|\widehat{\boldsymbol\mu}^{k}-\boldsymbol\mu^*\|_2 
            &\le \alpha_\varepsilon G(\boldsymbol w^*_{\mathcal I}, \boldsymbol\mu^*)^{1/2}  
            + \alpha_\varepsilon\big\|\bar{\boldsymbol\zeta}_{
            \boldsymbol w^*_{\mathcal I}}\big\|_2 + \alpha_\varepsilon
			\big\|\boldsymbol\mu^*-\widehat{\boldsymbol\mu}^{k-1}\big\|_2 + \Xi.
    \end{align}    
    Thus, we have obtained the desired recurrent inequality
    \begin{align}\label{mu:k3}
