			\boldsymbol\zeta_i\boldsymbol\zeta_i^\top)\bigg\|_{\rm op}^{1/2} + \sqrt{5\varepsilon}\,\big\|\bar{\boldsymbol\zeta}_{
        \boldsymbol w^*_{\mathcal I}}\big\|_2 + \Xi.\label{xi:tilde}
    \end{align}
