We define the worst-case risks for these two models 
	\begin{align}
	    R_{\max}^{\textup{HC}}(\widehat{\boldsymbol\mu}_n, \varepsilon) = \sup_{\boldsymbol\mu^*}\sup_{\mathbf P_n \in \mathcal{M}^{\textup{HC}}_n(\varepsilon, \boldsymbol\mu^*)} R_{\mathbf P_n} (\widehat{\boldsymbol\mu}_n, \boldsymbol\mu^*), \\ R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, \varepsilon) = \sup_{\boldsymbol\mu^*}\sup_{\mathbf P_n \in \mathcal{M}^{\textup{HDC}}_n(\varepsilon, \boldsymbol\mu^*)} R_{\mathbf P_n} (\widehat{\boldsymbol\mu}_n, \boldsymbol\mu^*).

\begin{align}
	    R_{\max}^{\textup{HC}}(\widehat{\boldsymbol\mu}_n, \varepsilon) = \sup_{\boldsymbol\mu^*}\sup_{\mathbf P_n \in \mathcal{M}^{\textup{HC}}_n(\varepsilon, \boldsymbol\mu^*)} R_{\mathbf P_n} (\widehat{\boldsymbol\mu}_n, \boldsymbol\mu^*), \\ R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, \varepsilon) = \sup_{\boldsymbol\mu^*}\sup_{\mathbf P_n \in \mathcal{M}^{\textup{HDC}}_n(\varepsilon, \boldsymbol\mu^*)} R_{\mathbf P_n} (\widehat{\boldsymbol\mu}_n, \boldsymbol\mu^*).
	\end{align}

\label{thm:lb-huber} There exists some universal constant $C> 0$ such that 
    \begin{equation}
        \inf_{\widehat{\boldsymbol\mu}_n} \sup_{\boldsymbol\mu^*} \sup_{\mathbf P_n \in \mathcal{M}^{\textup{HC}}_n(\varepsilon, \boldsymbol\mu^*)} \mathbf{P} \bigg( \| \widehat{\boldsymbol\mu}_n - \boldsymbol\mu^* \|_2 \ge C \| \boldsymbol\Sigma\|_{\textup{op}}^{1/2}\bigg[\sqrt{\frac{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}{n}} + \varepsilon \bigg]\bigg) \ge 1/2,
    \end{equation}
    for any $\varepsilon \in [0,1]$.

\begin{equation}
        \inf_{\widehat{\boldsymbol\mu}_n} \sup_{\boldsymbol\mu^*} \sup_{\mathbf P_n \in \mathcal{M}^{\textup{HC}}_n(\varepsilon, \boldsymbol\mu^*)} \mathbf{P} \bigg( \| \widehat{\boldsymbol\mu}_n - \boldsymbol\mu^* \|_2 \ge C \| \boldsymbol\Sigma\|_{\textup{op}}^{1/2}\bigg[\sqrt{\frac{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}{n}} + \varepsilon \bigg]\bigg) \ge 1/2,
    \end{equation}

There exist some universal constants $c, \widetilde{c} > 0$ such that 
if $n > \widetilde{c}$, then 
\begin{equation}
    \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}(\widehat{\boldsymbol\mu}_n, \boldsymbol\Sigma, \varepsilon) \ge c \| \boldsymbol\Sigma \|_{\textup{op}}^{1/2} \bigg(\sqrt{\frac{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}{n}} + \varepsilon\bigg). 
\end{equation}

\begin{equation}
        \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}(\widehat{\boldsymbol\mu}_n, \boldsymbol\Sigma, \varepsilon) \ge c \| \boldsymbol\Sigma \|_{\textup{op}}^{1/2} \bigg(\sqrt{\frac{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}{n}} + \varepsilon\bigg). 
    \end{equation}


    First, notice that it is sufficient to prove this bound for $\varepsilon > \sqrt{{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}/{n}}$. Indeed, if $\varepsilon < \sqrt{{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}/{n}}$ then one gets the desired lower bound by simply comparing GAC model with the standard outlier free model. More formally, 
    \begin{align}
        \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}(\widehat{\boldsymbol\mu}_n, \boldsymbol\Sigma, \varepsilon) \ge \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}^{\textup{OF}}(\widehat{\boldsymbol\mu}_n) = \sqrt{\frac{\mathop{\textup{Tr}}{\boldsymbol\Sigma}}{n}},
    \end{align}
    where $R_{\max}^{\textup{OF}}(\widehat{\boldsymbol\mu}_n)$ is the worst case risk in the classical outlier free setting where the observations are i.i.d. and drawn from $\mathcal{N}_p(\boldsymbol\mu^*, \boldsymbol\Sigma)$. 

    Since the GAC model is more general than HDC model, then one clearly has 
    \begin{align}\label{eq:ac-hdc}
        \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}(\widehat{\boldsymbol\mu}_n, \boldsymbol\Sigma, \varepsilon) \ge \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, \varepsilon).
    \end{align}
    On the other hand, in view of Eq. (4) from \citep{bateni2020minimax}, 
    for every $r>0$,
    \begin{align}
        R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, \varepsilon) + r e^{-n\varepsilon/6} \ge \sup_{\mathbf P_n \in \mathcal{M}^{\textup{HC}}_n(0.5\varepsilon, \boldsymbol\mu^*)} r\mathbf{P} \big( \| \widehat{\boldsymbol\mu}_n - \boldsymbol\mu \|_2 \ge r\big). 
    \end{align}
    Using the result of Theorem \ref{thm:lb-huber} and taking first $r = C \| \boldsymbol\Sigma\|_{\textup{op}}^{1/2}\big[\sqrt{{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}/{n}} + \varepsilon\big]$ then infimum of both sides one arrives at 
    \begin{align}\label{eq:lb-proof1}
        \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, \varepsilon) \ge (C/4) \| \boldsymbol\Sigma\|_{\textup{op}}^{1/2}\bigg[\sqrt{\frac{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}{n}} + \varepsilon\bigg]\big(1 - 2e^{-n\varepsilon/6}\big). 
    \end{align}
    Now, using $\varepsilon > \sqrt{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}/n}$ one gets that $n\varepsilon > \sqrt{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma} n} \ge \sqrt{n}$. Therefore, taking $n \ge 36\log^2(4)$, one can check that \eqref{eq:lb-proof1} yields
    \begin{align}
        \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, 2\varepsilon) \ge (C/8) \| \boldsymbol\Sigma\|_{\textup{op}}^{1/2}\bigg[\sqrt{\frac{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}{n}} + \varepsilon\bigg].
    \end{align}
Then, the final result follows from \eqref{eq:ac-hdc} with constants $c = C/8$ and $\widetilde{c} = 36\log^2(4)$.

\begin{align}
        \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}(\widehat{\boldsymbol\mu}_n, \boldsymbol\Sigma, \varepsilon) \ge \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}^{\textup{OF}}(\widehat{\boldsymbol\mu}_n) = \sqrt{\frac{\mathop{\textup{Tr}}{\boldsymbol\Sigma}}{n}},
    \end{align}

\begin{align}\label{eq:ac-hdc}
        \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}(\widehat{\boldsymbol\mu}_n, \boldsymbol\Sigma, \varepsilon) \ge \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, \varepsilon).
    \end{align}

\begin{align}
        R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, \varepsilon) + r e^{-n\varepsilon/6} \ge \sup_{\mathbf P_n \in \mathcal{M}^{\textup{HC}}_n(0.5\varepsilon, \boldsymbol\mu^*)} r\mathbf{P} \big( \| \widehat{\boldsymbol\mu}_n - \boldsymbol\mu \|_2 \ge r\big). 
    \end{align}

\begin{align}\label{eq:lb-proof1}
        \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, \varepsilon) \ge (C/4) \| \boldsymbol\Sigma\|_{\textup{op}}^{1/2}\bigg[\sqrt{\frac{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}{n}} + \varepsilon\bigg]\big(1 - 2e^{-n\varepsilon/6}\big). 
    \end{align}

\begin{align}
        \inf_{\widehat{\boldsymbol\mu}_n} R_{\max}^{\textup{HDC}}(\widehat{\boldsymbol\mu}_n, 2\varepsilon) \ge (C/8) \| \boldsymbol\Sigma\|_{\textup{op}}^{1/2}\bigg[\sqrt{\frac{\textbf{\textup{r}}_{\scriptscriptstyle\boldsymbol\Sigma}}{n}} + \varepsilon\bigg].
    \end{align}
